  Definition PRE17 : list byte := match rdn RSEGS (fun _ => None) (Z_to_bv 64 130377) 17 with Some l => l | None => [] end.
  Definition SUF1 : list byte := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40|30;!1+0!1,10!1+<1!1,1|600;-2RN$x;R!1+222!4'D':$~R!1+03!1,^L1!2'@3!1,7|@fd5c;}12$l;R2#1!1,B1").
